package com.ecopulse.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*; @Service public class MlClient { private final RestClient client; public MlClient(@Value("${app.ml-service-url}") String url){client=RestClient.builder().baseUrl(url).build();} public Map<?,?> forecast(List<Double> values,int horizon){return client.post().uri("/forecast").body(Map.of("values",values,"horizon",horizon)).retrieve().body(Map.class);} public Map<?,?> anomaly(List<Double> values){return client.post().uri("/anomaly").body(Map.of("values",values)).retrieve().body(Map.class);} }
